/// Given two 8-bit signed integers `n` (nonnegative) and `k` (at least 1),
/// compute the minimal nonnegative distance from `n` to a multiple of `k`.
/// Formally, let `r = n % k` (which lies in `0..k`), and return `min(r, k - r)`.
/// The result is guaranteed to lie in `0..k`.
fn solve(n: i8, k: i8) -> i8 {
    let r = n % k;
    r.min(k - r)
}

