        assert_eq!(solve(3, 5), 2);  // 3 is 2 away from 5
        assert_eq!(solve(10, 5), 0); // 10 is already a multiple of 5
        assert_eq!(solve(127, 127), 0);
        assert_eq!(solve(6, 4), 2);  // 6 % 4 = 2, 4 - 2 = 2
